<script lang="ts">
  import { onMount } from 'svelte';
  import { Palette, SlidersHorizontal, Download, Info, Check } from '@lucide/svelte';
  import UpdatePanel from './UpdatePanel.svelte';
  import logo from './assets/sflink-logo.svg';
  export let transferring = false;
  export let onAvailable: (version: string) => void = () => {};
  let category = 'Geral', selected = 'esmeralda';
  const themes = [
    { id: 'esmeralda', name: 'Esmeralda', description: 'A identidade original do SFLink', accent: '#20e3ad', base: '#090b0e', panel: '#0d1116', raised: '#14191f', muted: '#91a1b5', text: '#e4edf2', line: '#202830', dark: '#0c352a' },
    { id: 'oceano', name: 'Oceano', description: 'Azul sobre tons profundos', accent: '#69baff', base: '#09111d', panel: '#101d2d', raised: '#17283a', muted: '#a0b3cc', text: '#e6effa', line: '#293c55', dark: '#123857' },
    { id: 'ametista', name: 'Ametista', description: 'Violeta com contraste suave', accent: '#c4a1ff', base: '#130e1c', panel: '#1d1629', raised: '#2b203a', muted: '#b5a6c9', text: '#f0eafa', line: '#3c2e50', dark: '#3a2555' },
    { id: 'claro', name: 'Papel', description: 'Fundo claro e detalhes em verde', accent: '#087453', base: '#eaf0ed', panel: '#ffffff', raised: '#f0f5f2', muted: '#50665b', text: '#182b23', line: '#cbd9d1', dark: '#d8eee3' }
  ];
  function apply(id: string) {
    const theme = themes.find(t => t.id === id) || themes[0]; selected = theme.id;
    for (const [key, value] of Object.entries({ base: theme.base, panel: theme.panel, raised: theme.raised, muted: theme.muted, text: theme.text, line: theme.line, accent: theme.accent, 'accent-dark': theme.dark })) document.documentElement.style.setProperty(`--${key}`, value);
    document.documentElement.dataset.theme = theme.id;
    document.documentElement.style.colorScheme = theme.id === 'claro' ? 'light' : 'dark';
    try { localStorage.setItem('sflink-theme', theme.id); } catch {}
  }
  onMount(() => { try { apply(localStorage.getItem('sflink-theme') || 'esmeralda'); } catch { apply('esmeralda'); } });
</script>
<section class="page-section preferences">
  <div class="preferences-heading"><div><span>SEU ESPAÇO DE TRABALHO</span><h2>Configurações</h2><p>Ajuste a aparência e mantenha o SFLink atualizado.</p></div></div>
  <div class="settings-tabs" role="tablist" aria-label="Categorias de configurações">{#each [{name:'Geral',icon:SlidersHorizontal},{name:'Personalização',icon:Palette},{name:'Atualizações',icon:Download},{name:'Sobre',icon:Info}] as tab}<button role="tab" aria-selected={category === tab.name} class:chosen={category === tab.name} on:click={() => category = tab.name}><svelte:component this={tab.icon} size={16}/>{tab.name}</button>{/each}</div>
  <div hidden={category !== 'Geral'} class="settings-content">
    <h3>Arquivos e transferências</h3><p class="section-description">Comportamentos que preservam seus arquivos.</p>
    {#each [{ title:'Arquivos com o mesmo nome', description:'Downloads para abrir recebem outro nome quando já existe uma cópia. Transferências comuns não substituem arquivos.', value:'Preservar original' },{ title:'Exclusão no computador', description:'Os arquivos do PC vão para a Lixeira. No celular, a exclusão é definitiva e pede confirmação.', value:'Confirmar exclusão' },{ title:'Fotos e músicas', description:'Abrem no visualizador do SFLink. Arquivos do celular são baixados para a pasta aberta no PC.', value:'Dentro do aplicativo' },{ title:'Transferências', description:'Uma fila com progresso e cancelamento, sem executar dois arquivos ao mesmo tempo.', value:'Fila sequencial' }] as row}<div class="preference-row"><div><h4>{row.title}</h4><p>{row.description}</p></div><span>{row.value}</span></div>{/each}
    <h3 class="shortcut-title">Atalhos úteis</h3><div class="shortcut-grid">{#each [['Pesquisar na pasta','Ctrl + F'],['Selecionar resultados','Ctrl + A'],['Renomear','F2'],['Excluir com confirmação','Delete'],['Voltar / avançar','Botões laterais do mouse'],['Nova pasta','Ctrl + Shift + N']] as shortcut}<div><span>{shortcut[0]}</span><kbd>{shortcut[1]}</kbd></div>{/each}</div>
  </div>
  <div hidden={category !== 'Personalização'} class="settings-content"><h3>Escolha seu tema</h3><p class="section-description">A escolha é salva neste computador.</p><div class="theme-grid">{#each themes as theme}<button class="theme-option" class:chosen={selected === theme.id} aria-pressed={selected === theme.id} on:click={() => apply(theme.id)}><span class="theme-preview" style={`background:${theme.base};border-color:${theme.line}`}><span style={`background:${theme.panel}`}></span><span style={`background:${theme.panel};border-top:3px solid ${theme.accent}`}></span></span><span class="theme-name">{theme.name}{#if selected === theme.id}<Check size={17}/>{/if}</span><span class="theme-description">{theme.description}</span></button>{/each}</div></div>
  <div hidden={category !== 'Atualizações'} class="settings-content"><h3>Sempre na versão mais recente</h3><p class="section-description">O SFLink baixa, verifica, atualiza e reabre. Aguarde a fila de arquivos terminar antes de atualizar.</p><UpdatePanel {transferring} {onAvailable}/></div>
  <div hidden={category !== 'Sobre'} class="settings-content"><div class="about-brand"><img src={logo} alt="Logo SFLink"/><div><h3>SFLink</h3><p>Versão 0.5.0 · Windows</p></div></div><p class="section-description">Seus arquivos entre computador e Android, pela rede Wi-Fi local.</p><div class="preference-row"><div><h4>Conexão protegida</h4><p>O primeiro pareamento exige autorização no celular. Os dispositivos lembrados podem ter seu acesso revogado no Android.</p></div></div></div>
</section>
<style>
  .preferences{padding:30px;overflow:auto}.preferences-heading>div>span{font-size:10px;letter-spacing:1.5px;color:var(--accent)}h2{font-size:25px;margin:8px 0}p{color:var(--muted);font-size:12px;line-height:1.7}.settings-tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);padding:26px 0 14px;flex-wrap:wrap}.settings-tabs button{display:flex;align-items:center;gap:9px;border-radius:10px;padding:11px 16px;color:var(--muted);font-size:13px}.settings-tabs button.chosen{background:var(--accent-dark);color:var(--accent)}.settings-content{padding:26px 0 8px}.settings-content[hidden]{display:none}h3{font-size:17px;font-weight:600}.section-description{margin-top:8px;margin-bottom:22px;max-width:650px}.preference-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px 0;border-bottom:1px solid var(--line)}h4{font-size:13px;font-weight:500;margin:0 0 7px}.preference-row p{max-width:570px}.preference-row>span{color:var(--accent);background:var(--accent-dark);padding:8px 12px;border-radius:20px;white-space:nowrap;font-size:11px}.shortcut-title{margin:30px 0 18px}.shortcut-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 28px}.shortcut-grid>div{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 0;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}kbd{font:11px inherit;background:var(--raised);border:1px solid var(--line);padding:5px 8px;border-radius:6px;color:var(--text);white-space:nowrap}.theme-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;max-width:850px}.theme-option{text-align:left;border:1px solid var(--line);background:var(--raised);padding:15px;border-radius:18px}.theme-option.chosen{border-color:var(--accent)}.theme-preview{display:grid;grid-template-columns:1fr 3fr;gap:8px;border:1px solid;padding:12px;height:112px;border-radius:10px}.theme-preview>span{border-radius:5px}.theme-name{display:flex;justify-content:space-between;color:var(--text);font-size:14px;margin-top:15px}.theme-name :global(svg){color:var(--accent)}.theme-description{display:block;color:var(--muted);font-size:11px;margin-top:7px}.about-brand{display:flex;align-items:center;gap:20px;padding:25px 0}.about-brand img{width:70px;height:60px}.about-brand h3{font-size:28px;margin-bottom:7px}@media(max-width:1050px){.shortcut-grid{grid-template-columns:1fr}.preference-row{align-items:flex-start;flex-direction:column;gap:10px}}
</style>
